<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Str;
use Illuminate\Http\UploadedFile;
use App\Models\{User,Commune,Locality,WaterPoint,Incident,TechnicianProfile,Intervention};
use Inertia\Testing\AssertableInertia as Assert;
class EauRelaisTest extends TestCase {
 use RefreshDatabase;
 private $commune;private $locality;private $point;private $manager;private $tech;
 protected function setUp():void{parent::setUp();$this->withoutVite();$this->commune=Commune::create(['name'=>'Pilote']);$this->locality=Locality::create(['commune_id'=>$this->commune->id,'name'=>'Village']);$this->manager=User::create(['name'=>'Gestionnaire','email'=>'manager@test.test','password'=>'longpassword123','role'=>'gestionnaire','commune_id'=>$this->commune->id]);$this->tech=User::create(['name'=>'Technicien','email'=>'tech@test.test','password'=>'longpassword123','role'=>'technicien','commune_id'=>$this->commune->id]);$p=TechnicianProfile::create(['user_id'=>$this->tech->id,'phone'=>'0100000000','skills'=>['pompe'],'referenced'=>true]);$p->zones()->attach($this->commune->id);$this->point=WaterPoint::create(['name'=>'Pompe école','code'=>'P-1','locality_id'=>$this->locality->id,'equipment'=>'Pompe','community'=>'École','state'=>'hors_service']);}
 private function payload():array{return ['client_uuid'=>(string)Str::uuid(),'tracking_secret'=>str_repeat('a',64),'water_point_id'=>$this->point->id,'locality_id'=>$this->locality->id,'reporter_name'=>'École','phone'=>'+229 01 00 00 00 00','relationship'=>'ecole','problem'=>'pompe','description'=>'La pompe est bloquée depuis ce matin.','observed_at'=>today()->toDateString()];}
 private function incident():Incident{$this->postJson('/signalements',$this->payload())->assertCreated();return Incident::latest()->first();}
 public function test_public_pages_render():void{foreach(['/','/signaler','/points-eau','/suivre','/connexion'] as $url)$this->get($url)->assertOk();}
 public function test_idempotent_submission_and_tracking_secret():void{$data=$this->payload();$first=$this->postJson('/signalements',$data)->assertCreated()->json();$this->postJson('/signalements',$data)->assertOk()->assertJson(['reference'=>$first['reference']]);$this->assertDatabaseCount('incidents',1);$this->postJson('/suivi/rechercher',['reference'=>$first['reference'],'secret'=>'incorrect'])->assertNotFound();$track=$this->postJson('/suivi/rechercher',['reference'=>$first['reference'],'secret'=>$data['tracking_secret']])->assertOk();$track->assertJsonMissingPath('phone')->assertJsonMissingPath('reporter_name');$this->postJson('/signalements',array_merge($data,['tracking_secret'=>str_repeat('b',64)]))->assertForbidden();}
 public function test_full_repair_and_public_confirmation():void{$d=$this->payload();$ref=$this->postJson('/signalements',$d)->assertCreated()->json('reference');$i=Incident::first();$this->actingAs($this->manager)->post('/incidents/'.$i->id.'/statut',['status'=>'verification','comment'=>'Vérification sur le terrain.'])->assertRedirect();$this->post('/incidents/'.$i->id.'/interventions',['technician_id'=>$this->tech->id,'scheduled_at'=>today()->toDateString()])->assertRedirect();$v=Intervention::first();$this->actingAs($this->tech)->post('/interventions/'.$v->id,['acceptance'=>'acceptee','diagnosis'=>'Joint défectueux.','work_done'=>'Joint remplacé et essai effectué.','performed_at'=>today()->toDateString(),'repaired'=>true,'parts'=>[['name'=>'Joint','quantity'=>1,'state'=>'utilisee']]])->assertRedirect();$this->assertSame('repare',$i->fresh()->status);$this->postJson('/incidents/'.$i->id.'/confirmer',['working'=>true,'comment'=>'Tout fonctionne.'])->assertForbidden();$this->app['auth']->forgetGuards();$this->postJson('/suivi/retour',['reference'=>$ref,'secret'=>$d['tracking_secret'],'working'=>true,'comment'=>'Le débit est rétabli.'])->assertOk();$this->assertSame('confirme',$i->fresh()->status);$this->assertSame('fonctionnel',$this->point->fresh()->state);$this->assertNotNull($i->fresh()->confirmed_at);}
 public function test_foreign_commune_and_unassigned_technician_are_blocked():void{$i=$this->incident();$c=Commune::create(['name'=>'Autre']);$outsider=User::create(['name'=>'Autre','email'=>'other@test.test','password'=>'longpassword123','role'=>'gestionnaire','commune_id'=>$c->id]);$this->actingAs($outsider)->get('/incidents/'.$i->id)->assertForbidden();$this->postJson('/incidents/'.$i->id.'/statut',['status'=>'verification','comment'=>'Test interdit.'])->assertForbidden();$this->actingAs($this->tech)->get('/incidents/'.$i->id)->assertForbidden();}
 public function test_illegal_transition_and_future_observation_rejected():void{$i=$this->incident();$this->actingAs($this->manager)->postJson('/incidents/'.$i->id.'/statut',['status'=>'repare','comment'=>'Sans intervention.'])->assertUnprocessable();$d=$this->payload();$d['observed_at']=today()->addDay()->toDateString();$this->postJson('/signalements',$d)->assertUnprocessable();}
 public function test_file_validation_and_gps_consent():void{$d=$this->payload();$d['photo']=UploadedFile::fake()->create('unsafe.html',10,'text/html');$this->postJson('/signalements',$d)->assertUnprocessable();$d=$this->payload();$d['latitude']=6.3;$d['longitude']=2.4;$this->postJson('/signalements',$d)->assertUnprocessable();}
 public function test_dashboard_empty_delays_are_null_and_metrics_are_correct():void{$i=$this->incident();$this->actingAs($this->manager)->get('/tableau-de-bord')->assertInertia(fn(Assert $p)=>$p->component('Dashboard')->where('stats.response_hours',null)->where('stats.resolution_hours',null)->where('stats.open',1));$i->update(['status'=>'confirme','created_at'=>now()->subHours(48),'first_response_at'=>now()->subHours(46),'confirmed_at'=>now()]);$this->get('/tableau-de-bord')->assertInertia(fn(Assert $p)=>$p->where('stats.resolution_hours',48)->where('stats.response_hours',2)->where('stats.resolution_count',1));}
 public function test_manager_pages_render_and_admin_is_protected():void{$i=$this->incident();$this->actingAs($this->manager);foreach(['/tableau-de-bord','/incidents','/incidents/'.$i->id,'/techniciens','/entretiens'] as $url)$this->get($url)->assertOk();$this->get('/administration')->assertForbidden();}
 public function test_reopening_clears_confirmation_and_resets_water_point_state():void{$i=$this->incident();$i->update(['status'=>'confirme','confirmed_at'=>now()]);$this->point->update(['state'=>'fonctionnel']);$this->actingAs($this->manager)->post('/incidents/'.$i->id.'/statut',['status'=>'verification','comment'=>'La panne est réapparue.'])->assertRedirect();$this->assertNull($i->fresh()->confirmed_at);$this->assertSame('inconnu',$this->point->fresh()->state);}
 public function test_export_omits_private_contacts():void{$this->incident();$response=$this->actingAs($this->manager)->get('/tableau-de-bord?export=1')->assertOk();$csv=$response->streamedContent();$this->assertStringNotContainsString('+229',$csv);$this->assertStringContainsString('Référence',$csv);}

 public function test_public_catalog_never_exposes_maintenance_reports():void{\App\Models\Maintenance::create(['water_point_id'=>$this->point->id,'responsible_id'=>$this->tech->id,'scheduled_at'=>today(),'operations'=>'Diagnostic privé','report'=>'Contact privé +229 01 99 99 99 99']);$this->get('/points-eau')->assertInertia(fn(Assert $p)=>$p->component('Points')->missing('points.0.maintenances.0.report')->missing('points.0.maintenances.0.operations'));}
 public function test_admin_can_create_and_edit_technician_but_manager_cannot():void{$admin=User::create(['name'=>'Admin','email'=>'admin@test.test','password'=>'longpassword123','role'=>'admin']);$data=['name'=>'Nouvelle technicienne','email'=>'new@test.test','password'=>'longpassword123','role'=>'technicien','commune_id'=>$this->commune->id,'phone'=>'0100000000','skills'=>'Pompes, Réseaux','referenced'=>true];$this->actingAs($this->manager)->postJson('/administration/comptes',$data)->assertForbidden();$this->actingAs($admin)->post('/administration/comptes',$data)->assertRedirect();$new=User::where('email',$data['email'])->firstOrFail();$this->assertTrue($new->profile->referenced);$data['name']='Nom actualisé';unset($data['password']);$this->post('/administration/comptes/'.$new->id,$data)->assertRedirect();$this->assertSame('Nom actualisé',$new->fresh()->name);$this->get('/administration')->assertOk();}
 public function test_private_photos_are_protected_and_invalid_sizes_rejected():void{$i=$this->incident();$a=\App\Models\Attachment::create(['incident_id'=>$i->id,'path'=>'incidents/private.jpg','mime'=>'image/jpeg']);$this->get('/photos/'.$a->id)->assertRedirect('/connexion');$this->actingAs($this->tech)->get('/photos/'.$a->id)->assertForbidden();$d=$this->payload();$d['photo']=UploadedFile::fake()->create('photo.jpg',4000,'image/jpeg');$this->postJson('/signalements',$d)->assertUnprocessable();}
 public function test_scoped_listing_excludes_foreign_incident_and_private_responses_are_not_cached():void{$i=$this->incident();$c=Commune::create(['name'=>'Autre']);$u=User::create(['name'=>'Autre gestionnaire','email'=>'other-list@test.test','password'=>'longpassword123','role'=>'gestionnaire','commune_id'=>$c->id]);$this->actingAs($u)->get('/incidents')->assertInertia(fn(Assert $p)=>$p->has('incidents.data',0));$r=$this->actingAs($this->manager)->get('/incidents/'.$i->id)->assertOk();$this->assertStringContainsString('no-store',$r->headers->get('Cache-Control'));}
 public function test_demo_seeder_cannot_run_in_production():void{$this->app->instance('env','production');$this->expectException(\RuntimeException::class);(new \Database\Seeders\DatabaseSeeder)->run();}
 public function test_manager_can_link_an_unlisted_point_only_in_its_locality():void{$i=$this->incident();$i->update(['water_point_id'=>null]);$this->actingAs($this->manager)->post('/incidents/'.$i->id.'/statut',['water_point_id'=>$this->point->id,'comment'=>'Point identifié sur le terrain.'])->assertRedirect();$this->assertSame($this->point->id,$i->fresh()->water_point_id);$l=Locality::create(['name'=>'Autre village','commune_id'=>$this->commune->id]);$p=WaterPoint::create(['name'=>'Autre pompe','code'=>'P-2','locality_id'=>$l->id,'equipment'=>'Pompe','community'=>'Village']);$this->postJson('/incidents/'.$i->id.'/statut',['water_point_id'=>$p->id,'comment'=>'Mauvaise association.'])->assertUnprocessable();}
}
